def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 2

    def groups(length, is_separator):
        result = []
        start = 0
        for i in range(length):
            if is_separator(i):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    rows = groups(h, lambda r: all(v == sep for v in grid[r]))
    cols = groups(w, lambda c: all(grid[r][c] == sep for r in range(h)))

    out = []
    for r0, r1 in rows:
        row = []
        for c0, c1 in cols:
            cells = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            background = max(set(cells), key=cells.count)
            special = next((v for v in set(cells) if v != background), None)
            row.append(1 if special is not None and cells.count(special) == 2 else background)
        out.append(row)
    return out
